// Preview only — deliberately no Gmail node, no writing or sending
const P=$('Store Prospects').first().json.rows;
const D=$('Store Drafts').first().json.rows;
const X=$input.all().map(i=>i.json);
const key=r=>Number(r['#']||(Number(r.row_number)-1));
const val=x=>(x===undefined||x===null?'':String(x).trim());
const email=x=>val(x).toLowerCase();
const drafts=new Map(D.map(r=>[key(r),r]));
const exceptions=new Set(X.map(r=>Number(r.Prospect)).filter(Boolean));
const counts=new Map();
for(const r of P){const a=email(r['Public Email']);if(a)counts.set(a,(counts.get(a)||0)+1);}
const out=[];
for(const r of P){
 const n=key(r); if(n<56||n>75)continue;
 const d=drafts.get(n), to=email(d?.['Send To']), problems=[];
 if(val(r.Status)!=='Not contacted')problems.push('Not marked Not contacted');
 if(val(r['First Email Date']))problems.push('Existing first-send timestamp');
 if(!d)problems.push('Missing draft');
 if(d&&!/^draft\b/i.test(val(d['Draft Status'])))problems.push('Draft already sent/held');
 if(d&&val(d['Sent Date']))problems.push('Existing draft send timestamp');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to))problems.push('Invalid recipient');
 if(to!==email(r['Public Email']))problems.push('Recipient mismatch');
 if(counts.get(to)>1)problems.push('Duplicate address in tracker');
 if(exceptions.has(n))problems.push('Existing contact exception');
 if(/unsubscribe|opt.?out|do not contact|hard bounce|no such user|mailbox full|undeliver|blocked|connection refused/i.test([r.Outcome,r.Notes,r['Next Action']].map(val).join(' ')))problems.push('Potential suppression');
 if(!val(d?.Subject)||!val(d?.['Personalized Email Body']))problems.push('Missing subject/body');
 out.push({json:{prospect_id:n,business:val(r.Business),to,subject:val(d?.Subject),body:val(d?.['Personalized Email Body']),eligibility:problems.length?'HOLD_FOR_REVIEW':'DRAFT_READY_PENDING_GMAIL_RECONCILIATION_AND_APPROVAL',issues:problems,approved:false,sent:false}});
}
if(out.length!==20)throw Error('Expected 20 Batch 06 prospects; found '+out.length);
return out;

// FAIL CLOSED: read-only review. No item can be approved by this code.
const candidates=$('Build Batch 06 Preview - READ ONLY').all().map(x=>x.json);
const messages=$input.all().map(x=>x.json).filter(x=>x.id||x.threadId);
const normalized=x=>String(x??'').toLowerCase();
return candidates.map(c=>{
 const matching=messages.filter(m=>[m.from,m.to,m.snippet].some(v=>normalized(v).includes(normalized(c.to))));
 const blockers=[...(c.issues||[])];
 if(matching.length)blockers.push('Gmail correspondence found: review manually');
 if(messages.some(m=>!m.from&&!m.to))blockers.push('Gmail search output incomplete');
 // No automatic approval. Send path is disabled separately.
 return {json:{...c,gmail_matches:matching.length,gmail_threads:matching.map(m=>m.threadId||m.id),blockers,approved:false,authorized_to_send:false,eligibility:blockers.length?'HOLD_REVIEW':'GMAIL_CHECKED_PENDING_HUMAN_APPROVAL',sent:false}};
});
